const config = $json;
const now = config.testAsOf ? new Date(config.testAsOf) : new Date();
if (Number.isNaN(now.getTime())) throw new Error('testAsOf không hợp lệ');
const dateParts = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Ho_Chi_Minh', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(now);
const day = Number(dateParts.find((part) => part.type === 'day')?.value);
const automaticPhase = day === 25 ? 'OPENING' : day === 28 ? 'SECOND_REMINDER' : '';
const phase = String(config.testPhase || automaticPhase).trim();
return [{ json: { ...config, asOf: now.toISOString(), phase, skipSchedule: !phase, runId: String($execution.id) } }];

const response = $input.first().json;
const payload = response.data ?? response;
const reminders = Array.isArray(payload.reminders) ? payload.reminders : [];
const config = $('Xác định đợt thông báo').first().json;
if (reminders.length === 0) return [{ json: { ...config, skip: true, reviewPeriod: payload.reviewPeriod, phase: payload.phase, message: payload.message || 'Không có trường hợp cần nhắc.' } }];
return reminders.map((reminder) => ({ json: { ...config, ...reminder, skip: false } }));

const item = $json;
const esc = (value) => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const recipientEmail = String(item.testManagerEmail || item.recipient?.email || '').trim();
if (!recipientEmail) throw new Error('Người quản lý chưa có email nhận thông báo');
const employeeRows = item.employees.map((employee, index) => `<tr><td style="padding:8px;border:1px solid #ddd">${index + 1}</td><td style="padding:8px;border:1px solid #ddd"><strong>${esc(employee.fullName)}</strong><br/><small>${esc(employee.jobTitle || 'Chưa cập nhật chức danh')}</small></td><td style="padding:8px;border:1px solid #ddd">${esc(employee.departmentName)}</td></tr>`).join('');
const isSecond = item.phase === 'SECOND_REMINDER';
const title = isSecond ? 'NHẮC LẦN 2 - CÒN ĐÁNH GIÁ CHƯA NỘP' : 'MỞ KỲ ĐÁNH GIÁ KPI THÁNG';
const subject = isSecond ? `[Nhắc lần 2] ${item.pendingCount} đánh giá KPI ${item.reviewPeriodLabel} chưa nộp` : `[Thông báo] Mở kỳ đánh giá KPI ${item.reviewPeriodLabel}`;
const intro = isSecond ? `Hệ thống ghi nhận còn <strong>${item.pendingCount} nhân viên</strong> thuộc phạm vi phụ trách chưa có đánh giá KPI.` : `Kỳ đánh giá KPI <strong>${esc(item.reviewPeriodLabel)}</strong> đã được mở. Anh/chị có <strong>${item.pendingCount} nhân viên</strong> cần hoàn thành đánh giá.`;
const emailHtml = `<p>Chào <strong>${esc(item.recipient.fullName)}</strong>,</p><p>${intro}</p><table style="border-collapse:collapse;width:100%"><thead><tr><th style="padding:8px;border:1px solid #ddd">STT</th><th style="padding:8px;border:1px solid #ddd">Nhân viên</th><th style="padding:8px;border:1px solid #ddd">Phòng ban</th></tr></thead><tbody>${employeeRows}</tbody></table><p>Hạn hoàn thành: <strong>${esc(item.deadline)}</strong>.</p><p><a href="${esc(item.reviewFormUrl)}">Mở biểu mẫu đánh giá</a></p><p><em>Đây là thông báo tự động từ hệ thống Nhân sự.</em></p>`;
const telegramText = `📊 <b>${title}</b>\n\nKỳ: <b>${esc(item.reviewPeriodLabel)}</b>\nNgười phụ trách: <b>${esc(item.recipient.fullName)}</b>\nSố đánh giá còn thiếu: <b>${item.pendingCount}</b>\nHạn hoàn thành: <b>${esc(item.deadline)}</b>`;
return { json: { ...item, recipientEmail, emailSubject: subject, emailHtml, telegramText, pendingEmployeeIds: item.employees.map((employee) => employee.id) } };

const source = $('Soạn nội dung đánh giá bằng tiếng Việt').item.json;
const emailResult = $('Gửi thư cho quản lý').item.json || {};
const telegramResult = $('Thông báo kênh đánh giá').item.json || {};
const emailNotified = !emailResult.error && (!Array.isArray(emailResult.rejected) || emailResult.rejected.length === 0);
const telegramNotified = !telegramResult.error && telegramResult.ok !== false;
const successCount = Number(emailNotified) + Number(telegramNotified);
const status = successCount === 2 ? 'SENT' : successCount > 0 ? 'PARTIAL' : 'FAILED';
return { json: { ...source, emailNotified, telegramNotified, status, detail: `Email=${emailNotified}; Telegram=${telegramNotified}` } };
